    if (node === null) return;
    slots.set(i, (slots.get(i) ?? 0) + node.val);
    spread(node.left, 2 * i + 1);          // children of slot i: 2i+1 and 2i+2
    spread(node.right, 2 * i + 2);
  }
  spread(a, 0);
  spread(b, 0);
  function build(i) {
