void spread(TreeNode node, long i, Map<Long, Integer> slots) {
    if (node == null) return;
    slots.merge(i, node.val, Integer::sum);
    spread(node.left, 2 * i + 1, slots);          // children of slot i: 2i+1 and 2i+2
    spread(node.right, 2 * i + 2, slots);
}

TreeNode build(long i, Map<Long, Integer> slots) {
    if (!slots.containsKey(i)) return null;
    return new TreeNode(slots.get(i), build(2 * i + 1, slots), build(2 * i + 2, slots));
}

void spread(TreeNode* node, long long i, unordered_map<long long, int>& slots) {
    if (node == nullptr) return;
    slots[i] += node->val;
    spread(node->left, 2 * i + 1, slots);         // children of slot i: 2i+1 and 2i+2
    spread(node->right, 2 * i + 2, slots);
}

TreeNode* build(long long i, unordered_map<long long, int>& slots) {
    auto it = slots.find(i);
    if (it == slots.end()) return nullptr;
    return new TreeNode(it->second, build(2 * i + 1, slots), build(2 * i + 2, slots));
}

