}

function mergeTrees(a, b) {
  if (a === null && b === null) return null;
  const node = new TreeNode((a ? a.val : 0) + (b ? b.val : 0));   // a fresh node
  node.left = mergeTrees(a ? a.left : null, b ? b.left : null);
  node.right = mergeTrees(a ? a.right : null, b ? b.right : null);
  return node;
}

public TreeNode mergeTrees(TreeNode a, TreeNode b) {
    if (a == null && b == null) return null;
    TreeNode node = new TreeNode((a != null ? a.val : 0) + (b != null ? b.val : 0));   // a fresh node
    node.left = mergeTrees(a != null ? a.left : null, b != null ? b.left : null);
    node.right = mergeTrees(a != null ? a.right : null, b != null ? b.right : null);
    return node;
}

TreeNode* mergeTrees(TreeNode* a, TreeNode* b) {
    if (!a && !b) return nullptr;
    TreeNode* node = new TreeNode((a ? a->val : 0) + (b ? b->val : 0));   // a fresh node
    node->left = mergeTrees(a ? a->left : nullptr, b ? b->left : nullptr);
    node->right = mergeTrees(a ? a->right : nullptr, b ? b->right : nullptr);
    return node;
}

function mergeTrees(a, b) {
  if (a === null) return b;             // only b has a node here: reuse b's subtree
  if (b === null) return a;             // only a has one: keep a's subtree
  a.val += b.val;                       // both do: add b into a
  a.left = mergeTrees(a.left, b.left);
  a.right = mergeTrees(a.right, b.right);
  return a;
}

